window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-949725588fa7e1eb"]={"versions": [{"id": "FIG-949725588fa7e1eb", "releases": ["R2.1.20", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm zur Veranschaulichung des Zusammenspiels zwischen AUTOSAR Software-Components (SW-Cs) auf der Anwendungsebene und den Basissoftware-Modulen Diagnostic Event Manager (DEM) sowie Function Inhibition Manager (FIM) im Systemkontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier primäre Blöcke sowie eine tabellarische Inhibit-Konfiguration:</p>\n<ul class=\"fig-list\">\n<li><strong>Front-left Anti-pinch Sensor SW-C</strong>: Software-Komponente mit einem Require-Port <code>R</code> zur Anwendungs-Kommunikation und einer Schnittstelle/Zuordnung zu <code>DEM</code> bezüglich <code>EventId: anti_pinch</code>.</li>\n<li><strong>Front-left Window-lifter SW-C</strong>: Software-Komponente mit zwei Provide-Ports <code>P</code>, einem Require-Port <code>R</code> und einer Kontrollschnittstelle/Zuordnung zu <code>FIM</code> bezüglich <code>FunctionId: Automatic_window_closing_allowed</code>.</li>\n<li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Erfassung und Verwaltung von Diagnose-Events (<code>anti_pinch</code>).</li>\n<li><strong>FIM (Function Inhibition Manager)</strong>: BSW-Modul zur Auswertung von Funktions-Inhibitionen und Steuerung der Freigabe von Funktionalitäten (<code>Automatic_window_closing_allowed</code>).</li>\n<li><strong>Verbindungen & Zuordnungen</strong>:</li>\n<li>Horizontale Verbindung zwischen <code>R</code>-Port der <code>Front-left Anti-pinch Sensor SW-C</code> und <code>P</code>-Port der <code>Front-left Window-lifter SW-C</code>.</li>\n<li>Vertikale Schnittstellenanbindung von <code>Front-left Anti-pinch Sensor SW-C</code> an <code>DEM</code> (markiert mit <code>EventId: anti_pinch</code>).</li>\n<li>Vertikale Schnittstellenanbindung von <code>Front-left Window-lifter SW-C</code> an <code>FIM</code> (markiert mit <code>FunctionId: Automatic_window_closing_allowed</code>).</li>\n<li>Gestrichelte Beziehung mit Pfeil zwischen <code>DEM</code> und <code>FIM</code> über eine Mapping-Tabelle.</li>\n<li><strong>Konfigurationstabelle</strong>:</li>\n<li>Kopf: <code>FunctionId: Automatic_window_closing_allowed</code></li>\n<li>Spalten: <code>EventId</code> und <code>Mask</code></li>\n<li>Eintrag: <code>EventId = anti_pinch</code>, <code>Mask = Last_Failed</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Front-left Anti-pinch Sensor SW-C</code> meldet das Auftreten bzw. den Status des Diagnoseereignisses <code>anti_pinch</code> an den <code>DEM</code>.</li>\n<li>Der <code>DEM</code> stellt Statusänderungen des Ereignisses <code>anti_pinch</code> dem <code>FIM</code> bereit.</li>\n<li>Der <code>FIM</code> wertet anhand der konfigurierten Maske (<code>Last_Failed</code>) aus, ob das Ereignis aktiv/fehlgeschlagen ist.</li>\n<li>Bei erfüllter Maskierungsbedingung inhibiert der <code>FIM</code> die Funktion <code>Automatic_window_closing_allowed</code>.</li>\n<li>Die <code>Front-left Window-lifter SW-C</code> fragt vor Ausführung der automatischen Fensterheberschließung den Freigabestatus der <code>FunctionId: Automatic_window_closing_allowed</code> beim <code>FIM</code> ab (bzw. erhält die Inhibition) und unterbindet das automatische Schließen bei aktivem Fehler.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Konfigurations- und Architekturszenario (Use Case Pattern) für den Einsatz des FIM gemäß SWS FIM:</p>\n<ul class=\"fig-list\">\n<li>Zeigt die funktionale Entkopplung zwischen Fehlererfassung (<code>DEM</code>) und funktionaler Deaktivierung (<code>FIM</code>) auf Software-Komponentenebene.</li>\n<li>Verdeutlicht das Zuordnungsprinzip, bei dem Software-Komponenten nicht direkt anwendungsspezifisch Diagnoseereignisse auswerten müssen, sondern standardisierte FIM-Funktionsbezeichner (<code>FunctionId</code>) und Inhibitions-Kriterien (hier Event-Maske <code>Last_Failed</code>) zur Ausführungssteuerung nutzen.</li>\n</ul>"}, {"id": "FIG-01bbda81c8460a6e", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Interaktionsdiagramm zur Veranschaulichung des Zusammenspiels zwischen AUTOSAR Software-Components (SW-Cs) auf der Anwendungsebene und den Basissoftware-Modulen Diagnostic Event Manager (DEM) sowie Function Inhibition Manager (FIM) im Systemkontext der AUTOSAR Classic Platform.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst vier primäre Blöcke sowie eine tabellarische Inhibit-Konfiguration:</p>\n<ul class=\"fig-list\">\n<li><strong>Front-left Anti-pinch Sensor SW-C</strong>: Software-Komponente mit einem Require-Port <code>R</code> zur Anwendungs-Kommunikation und einer Schnittstelle/Zuordnung zu <code>DEM</code> bezüglich <code>EventId: anti_pinch</code>.</li>\n<li><strong>Front-left Window-lifter SW-C</strong>: Software-Komponente mit zwei Provide-Ports <code>P</code>, einem Require-Port <code>R</code> und einer Kontrollschnittstelle/Zuordnung zu <code>FIM</code> bezüglich <code>FunctionId: Automatic_window_closing_allowed</code>.</li>\n<li><strong>DEM (Diagnostic Event Manager)</strong>: BSW-Modul zur Erfassung und Verwaltung von Diagnose-Events (<code>anti_pinch</code>).</li>\n<li><strong>FIM (Function Inhibition Manager)</strong>: BSW-Modul zur Auswertung von Funktions-Inhibitionen und Steuerung der Freigabe von Funktionalitäten (<code>Automatic_window_closing_allowed</code>).</li>\n<li><strong>Verbindungen & Zuordnungen</strong>:</li>\n<li>Horizontale Verbindung zwischen <code>R</code>-Port der <code>Front-left Anti-pinch Sensor SW-C</code> und <code>P</code>-Port der <code>Front-left Window-lifter SW-C</code>.</li>\n<li>Vertikale Schnittstellenanbindung von <code>Front-left Anti-pinch Sensor SW-C</code> an <code>DEM</code> (markiert mit <code>EventId: anti_pinch</code>).</li>\n<li>Vertikale Schnittstellenanbindung von <code>Front-left Window-lifter SW-C</code> an <code>FIM</code> (markiert mit <code>FunctionId: Automatic_window_closing_allowed</code>).</li>\n<li>Gestrichelte Beziehung mit Pfeil zwischen <code>DEM</code> und <code>FIM</code> über eine Mapping-Tabelle.</li>\n<li><strong>Konfigurationstabelle</strong>:</li>\n<li>Kopf: <code>FunctionId: Automatic_window_closing_allowed</code></li>\n<li>Spalten: <code>EventId</code> und <code>Mask</code></li>\n<li>Eintrag: <code>EventId = anti_pinch</code>, <code>Mask = Last_Failed</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Die <code>Front-left Anti-pinch Sensor SW-C</code> meldet das Auftreten bzw. den Status des Diagnoseereignisses <code>anti_pinch</code> an den <code>DEM</code>.</li>\n<li>Der <code>DEM</code> stellt Statusänderungen des Ereignisses <code>anti_pinch</code> dem <code>FIM</code> bereit.</li>\n<li>Der <code>FIM</code> wertet anhand der konfigurierten Maske (<code>Last_Failed</code>) aus, ob das Ereignis aktiv/fehlgeschlagen ist.</li>\n<li>Bei erfüllter Maskierungsbedingung inhibiert der <code>FIM</code> die Funktion <code>Automatic_window_closing_allowed</code>.</li>\n<li>Die <code>Front-left Window-lifter SW-C</code> fragt vor Ausführung der automatischen Fensterheberschließung den Freigabestatus der <code>FunctionId: Automatic_window_closing_allowed</code> beim <code>FIM</code> ab (bzw. erhält die Inhibition) und unterbindet das automatische Schließen bei aktivem Fehler.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Exemplarisches Konfigurations- und Architekturszenario (Use Case Pattern) für den Einsatz des FIM gemäß SWS FIM:</p>\n<ul class=\"fig-list\">\n<li>Zeigt die funktionale Entkopplung zwischen Fehlererfassung (<code>DEM</code>) und funktionaler Deaktivierung (<code>FIM</code>) auf Software-Komponentenebene.</li>\n<li>Verdeutlicht das Zuordnungsprinzip, bei dem Software-Komponenten nicht direkt anwendungsspezifisch Diagnoseereignisse auswerten müssen, sondern standardisierte FIM-Funktionsbezeichner (<code>FunctionId</code>) und Inhibitions-Kriterien (hier Event-Maske <code>Last_Failed</code>) zur Ausführungssteuerung nutzen.</li>\n</ul>"}], "trans": [{"from": "FIG-949725588fa7e1eb", "to": "FIG-01bbda81c8460a6e", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-01bbda81c8460a6e", "to": "FIG-949725588fa7e1eb", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
